<script setup lang="ts">import { nextTick,ref,watch } from "vue";import type { DismissReason } from "../../api/recommendations";const props=defineProps<{open:boolean;pending:boolean;error:string|null;returnFocus:HTMLElement|null}>();const emit=defineEmits<{close:[];confirm:[DismissReason]}>();const reason=ref<DismissReason>('off_topic');const panel=ref<HTMLElement|null>(null);function close(){if(!props.pending)emit('close')}function keydown(e:KeyboardEvent){if(e.key==='Escape'){e.preventDefault();close();return}if(e.key==='Tab'&&panel.value){const nodes=[...panel.value.querySelectorAll<HTMLElement>('button,select,[href],[tabindex]:not([tabindex="-1"])')];if(!nodes.length)return;const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}}watch(()=>props.open,async open=>{if(open){reason.value='off_topic';await nextTick();panel.value?.focus()}else props.returnFocus?.focus()});</script>
<template><div v-if="open" class="backdrop" @click.self="close"><section ref="panel" role="dialog" aria-modal="true" aria-labelledby="dismiss-title" tabindex="-1" @keydown="keydown"><h2 id="dismiss-title">忽略此推荐</h2><p>请选择原因。该决定会保存到本次推荐运行。</p><label for="dismiss-reason">忽略原因</label><select id="dismiss-reason" v-model="reason"><option value="duplicate">重复文献</option><option value="off_topic">主题偏离</option><option value="unsuitable_study_type">研究类型不适合</option><option value="other">其他</option></select><p v-if="error" class="error" role="alert">{{ error }}</p><footer><button type="button" :disabled="pending" @click="close">取消</button><button class="confirm" type="button" :disabled="pending" @click="emit('confirm',reason)">{{ pending?'正在保存…':'确认忽略' }}</button></footer></section></div></template>
<style scoped>.backdrop{position:fixed;z-index:45;inset:0;display:grid;place-items:center;padding:16px;background:rgb(15 30 60/.28)}section{width:min(420px,100%);box-sizing:border-box;padding:22px;border:1px solid #dce5f0;border-radius:12px;background:#fff;box-shadow:0 12px 36px rgb(15 23 42/.16);outline:none}h2{margin:0;font-size:18px}p{color:#475569;font-size:13px;line-height:1.6}label{display:block;margin-bottom:6px;font-size:13px;font-weight:700}select{width:100%;height:44px;padding:0 10px;border:1px solid #cbd8e8;border-radius:8px;background:#fff}.error{color:#b42318}footer{display:flex;justify-content:flex-end;gap:9px;margin-top:20px}button{min-height:40px;padding:0 14px;border:1px solid #cbd8e8;border-radius:7px;background:#fff;color:#17345f;font-weight:700}.confirm{border-color:#b42318;background:#b42318;color:#fff}</style>
